{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A practical, event-based series for building steady habits and better days. Outcomes, simple frameworks, and guided practices.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="8" fill="#F0EFEA"></rect><circle cx="24" cy="24" r="10" fill="#D1E8E2"></circle></svg>
      <div class="brand-text">
        <strong class="name">{{BUSINESS_NAME}}</strong>
        <small class="tag">{{TAGLINE}}</small>
      </div>
    </div>
    <nav class="main-nav" aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="programs.html">Series</a>
      <a href="services.html">Offerings</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
    <div class="actions">
      <a class="btn btn-ghost" href="pricing.html">Investment</a>
      <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <section class="hero reveal split-diagonal">
      <div class="hero-left">
        <h1>Events that teach steady habits, not quick fixes</h1>
        <p class="lead">Join a short series of guided gatherings where outcomes are framed as daily, repeatable micro-practices. Tracks built on habits, habit stacks, and simple frameworks you can repeat.</p>
        <div class="hero-ctas">
          <a class="btn btn-large" href="programs.html">See upcoming series</a>
          <button id="tryNowBtn" class="btn btn-outline">Try a guided exercise</button>
        </div>
        <ul class="meta-list">
          <li>Practical frameworks</li>
          <li>Group sessions & home practice</li>
          <li>Outcomes you can measure</li>
        </ul>
      </div>
      <div class="hero-right">
        <div class="card card-sample">
          <svg class="pattern" viewBox="0 0 200 200" preserveAspectRatio="none" aria-hidden="true"><use href="assets/img/pattern.svg#p"/></svg>
          <div class="card-content">
            <h3>Upcoming: Focused Rhythm</h3>
            <p>4-week event series — weekly live group + guided home practices.</p>
            <a class="btn" href="programs.html">Join the next cohort</a>
          </div>
        </div>
      </div>
    </section>

    <section class="gallery reveal" aria-labelledby="gallery-title">
      <h2 id="gallery-title">What a series looks like</h2>
      <div class="grid">
        <article>
          <h3>Weekly Live Session</h3>
          <p>Interactive group time to learn a framework, practice, and set clear next actions.</p>
        </article>
        <article>
          <h3>Short Home Practices</h3>
          <p>Five-to-ten minute habits you build day by day—tracked in simple ways.</p>
        </article>
        <article>
          <h3>Accountability Check-ins</h3>
          <p>Optional peer check-ins and small group accountability between sessions.</p>
        </article>
      </div>
    </section>

    <section class="what-to-expect reveal">
      <h2>How outcomes map to habits</h2>
      <p>We break outcomes into three repeatable parts: a focused habit, a context cue, and a small tracking loop. No medical advice—only reproducible routines and clearer indicators of progress.</p>
      <div class="bullets">
        <div>
          <strong>Habit</strong>
          <p>One action you can do consistently.</p>
        </div>
        <div>
          <strong>Cue</strong>
          <p>An anchor in your day so it doesn't rely on willpower.</p>
        </div>
        <div>
          <strong>Measure</strong>
          <p>Simple ways to notice progress and adjust.</p>
        </div>
      </div>
    </section>

    <section class="objections reveal">
      <h2>Common questions</h2>
      <dl>
        <dt>Will this need lots of time?</dt>
        <dd>No—sessions are focused and home practices are five-to-ten minutes.</dd>
        <dt>Is this a therapy program?</dt>
        <dd>No. These are habit and life-design practices, not medical or therapeutic interventions.</dd>
        <dt>What if I miss a week?</dt>
        <dd>Each week stands alone with a repeatable practice you can resume any time.</dd>
      </dl>
    </section>

    <section class="callout reveal">
      <h2>Ready to learn a practical rhythm?</h2>
      <p>Join a multi-week series that teaches frameworks and tiny habits you can keep using.</p>
      <div class="callout-actions">
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn btn-ghost" href="contact.html">Ask a question</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div>
      <p>Serving {{CITY}}, {{STATE}}. Contact <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
    </div>
    <nav class="footer-nav">
      <a href="about.html">About</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Testimonials</a>
      <a href="sitemap.xml">Sitemap</a>
    </nav>
  </footer>

  <!-- Guided exercise modal -->
  <div id="guidedModal" class="modal" aria-hidden="true" role="dialog" aria-modal="true">
    <div class="modal-panel" role="document">
      <button class="modal-close" id="modalClose" aria-label="Close">×</button>
      <h3 id="modalTitle">Try a short practice</h3>
      <p class="modal-desc">Choose a short guided exercise—breathing, journaling, or intention setting.</p>
      <div class="modal-controls">
        <button data-action="breathing" class="btn">Breathing</button>
        <button data-action="journaling" class="btn">Journaling</button>
        <button data-action="intention" class="btn">Set an intention</button>
      </div>
      <div id="exerciseArea" class="exercise-area" aria-live="polite"></div>
    </div>
  </div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
